const structuredData = parsedArray.map(item => {
  return {
    order_id: item[0],               // 订单编号，如 "CGDD000001"
    order_date: item[1],             // 订单日期，如 "2018-01-09T00:00:00"
    buyer: item[2],                  // 采购方，如 "金蝶蓝海实业集团"
    supplier: item[3],               // 供应商，如 "金蝶美华公司"
    product_code: item[4],           // 产品编码，如 "2.1110009"
    product_name: item[5],           // 产品名称，如 "磨砂保护壳（多单位）"
    product_spec: item[6],           // 产品规格（可能为空），如 " "
    quantity: parseFloat(item[7]),   // 数量（转为浮点数），如 10.0
    unit_price: parseFloat(item[8]), // 单价（转为浮点数），如 15.0
    unit: item[9],                    // 单位，如 "件"
    id: item[10],                    // 明细内码
    DELIVERYDATE: item[11],                    // 交货日期
    DOCUMENTSTATUS:item[12],
    MRPTERMINATESTATUS:item[13],
    MRPCLOSESTATUS:item[14],
    // 添加时间戳或版本标记
    last_updated: new Date().toISOString()
  };
});

// 返回结构化数据（n8n 会自动处理数组的批量传递）
return structuredData;

